"use client";
import { useEffect, useState } from "react";
import { getCookie, hasCookie } from "cookies-next";
import getUserDetail from "@/services/auth/userDetail";
import Breadcrumb from "@/components/header/breadcrumb";
import postProfileUpdate from "@/services/auth/profile/updateProfile";
import Menu from "./menu";
import { labelCls, inputCls } from "@/components/profile-page/fieldStyles";

export default function SecurityInformation() {
  const [userLoading, setUserLoading] = useState(true);
  const [user, setUser] = useState({
    name: "",
    email: "",
  });
  const [userData, setUserData] = useState({
    name: "",
    firstName: "",
    lastName: "",
    email: "",
    currentPassword: "",
    newPassword: "",
    newPasswordAgain: "",
    countryId: "",
    travelStyles: [],
    lodgings: [],
    activities: [],
    categories: [],
  });
  const [loading, setLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [submitStatus, setSubmitStatus] = useState("");

  const updateSubmit = async () => {
    if (userData.email && userData.firstName && userData.lastName) {
      if (
        userData.currentPassword != "" &&
        userData.newPassword != "" &&
        userData.newPassword !== userData.newPasswordAgain
      ) {
        setErrorMessage("Passwords do not match.");
        setSubmitStatus("error");
      } else {
        if (
          userData.currentPassword != "" &&
          userData.newPassword !== userData.newPasswordAgain &&
          userData.newPassword.length < 6
        ) {
          setErrorMessage("Your password must be at least 6 characters.");
        } else {
          setSubmitStatus("");
          setErrorMessage("");

          try {
            setLoading(true);

            const res = await postProfileUpdate({
              requestData: userData,
              token: getCookie("auth-token"),
            });

            if ("success" in res) {
              if (res.success) {
                setErrorMessage("");
                setSubmitStatus("success");

                setUserData({
                  ...userData,
                  currentPassword: "",
                  newPassword: "",
                  newPasswordAgain: "",
                });
              } else {
                setErrorMessage(res.message);
                setSubmitStatus("error");
              }
            } else {
              setErrorMessage(res.errors[Object.keys(res.errors)[0]][0]);
              setSubmitStatus("error");
            }
          } catch (error: any) {
            setSubmitStatus("error");
            setErrorMessage(
              "The e-mail address is registered in our system. Please provide any other information."
            );
          }
          setLoading(false);
        }
      }
    } else {
      setErrorMessage("Please fill in the required fields.");
      setSubmitStatus("error");
    }
  };

  const fetchUserDetail = async () => {
    const userData = await getUserDetail({ token: getCookie("auth-token") });
    return userData;
  };

  useEffect(() => {
    if (hasCookie("auth-token")) {
      try {
        fetchUserDetail().then((res: any) => {
          setUserData({
            name: res.name,
            firstName: res.first_name,
            lastName: res.last_name,
            email: res.email,
            currentPassword: "",
            newPassword: "",
            newPasswordAgain: "",
            countryId: res.country_id,
            travelStyles: res.meta.preffered_travel_styles,
            lodgings: res.meta.preffer_lodgings,
            activities: res.meta.activities,
            categories: res.meta.categories,
          });
          setUser({ name: res.name, email: res.email });
          setUserLoading(false);
        });
      } catch (e) {}
    } else {
      setUserLoading(false);
    }
  }, []);

  return (
    <main className="tw-font-display">
      <div className="tw-mx-auto tw-max-w-[1320px] tw-px-4 tw-py-6">
        <Breadcrumb items={[{ pageTitle: "Profile", pageUrl: "/profile" }]} />
        <h1 className="tw-mt-2 tw-mb-5 tw-text-[clamp(22px,2.6vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
          Security Information
        </h1>

        <div className="tw-grid tw-grid-cols-1 tw-gap-6 md:tw-grid-cols-[260px_minmax(0,1fr)]">
          <div>
            <Menu />
          </div>

          <div>
            <div className="tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-p-6 tw-shadow-[0_8px_30px_rgba(20,16,28,0.05)]">
              <h2 className="tw-mb-1 tw-text-lg tw-font-bold tw-text-[#14101c]">Change Password</h2>
              <p className="tw-mb-5 tw-mt-0 tw-text-sm tw-text-[#6b6577]">
                Keep your account secure with a strong password you don&apos;t use elsewhere.
              </p>

              {submitStatus == "error" && errorMessage && (
                <div className="tw-mb-4 tw-rounded-xl tw-border tw-border-solid tw-border-[#f3c2c2] tw-bg-[#fdecec] tw-px-4 tw-py-3 tw-text-sm tw-text-[#b23838]">
                  {errorMessage}
                </div>
              )}
              {submitStatus == "success" && (
                <div className="tw-mb-4 tw-rounded-xl tw-border tw-border-solid tw-border-[#bfe6cd] tw-bg-[#eafaf0] tw-px-4 tw-py-3 tw-text-sm tw-text-[#1f8a4c]">
                  Your password has been updated successfully.
                </div>
              )}

              <div className="tw-grid tw-grid-cols-1 tw-gap-5 md:tw-grid-cols-2">
                <div className="md:tw-col-span-2 md:tw-max-w-[calc(50%-0.625rem)]">
                  <label htmlFor="currentPasswordInput" className={labelCls}>
                    Current Password
                  </label>
                  <input
                    type="password"
                    className={inputCls}
                    id="currentPasswordInput"
                    value={userData.currentPassword}
                    autoComplete="new-password"
                    onChange={(event: any) => {
                      setUserData({ ...userData, currentPassword: event.target.value });
                    }}
                  />
                </div>

                <div>
                  <label htmlFor="newPasswordInput" className={labelCls}>
                    New Password
                  </label>
                  <input
                    type="password"
                    className={inputCls}
                    id="newPasswordInput"
                    value={userData.newPassword}
                    autoComplete="new-password"
                    onChange={(event: any) => {
                      setUserData({ ...userData, newPassword: event.target.value });
                    }}
                  />
                </div>

                <div>
                  <label htmlFor="passwordAgainInput" className={labelCls}>
                    New Password Again
                  </label>
                  <input
                    type="password"
                    className={inputCls}
                    id="passwordAgainInput"
                    value={userData.newPasswordAgain}
                    onChange={(event: any) => {
                      setUserData({ ...userData, newPasswordAgain: event.target.value });
                    }}
                  />
                </div>
              </div>

              <div className="tw-mt-6">
                {loading ? (
                  <button
                    type="button"
                    disabled
                    className="tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-border-0 tw-bg-[#854ec9] tw-px-6 tw-py-2.5 tw-text-sm tw-font-semibold tw-text-white tw-opacity-70"
                  >
                    <span className="tw-inline-block tw-h-4 tw-w-4 tw-animate-spin tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent" />
                    Loading...
                  </button>
                ) : (
                  <button
                    type="button"
                    onClick={updateSubmit}
                    className="tw-rounded-full tw-border-0 tw-bg-[#854ec9] tw-px-8 tw-py-2.5 tw-text-sm tw-font-semibold tw-text-white tw-transition-colors hover:tw-bg-[#6a3da4]"
                  >
                    Save
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}
